*tone;
if negative_comp_qa=. then negative_comp_qa=0;
if positive_comp_qa=. then positive_comp_qa=0;
if negative_comp_pres=. then negative_comp_pres=0;
if positive_comp_pres=. then positive_comp_pres=0;

*jargon;
if num_jargon_words_comp_pres=. then num_jargon_words_comp_pres=0;
if num_jargon_words_comp_qa=. then num_jargon_words_comp_qa=0;

if 2011>=year(call_date)>=2002;
if nmiss(size,bm,momentum,idvol,coverage,disp,ibesmv,loss,itemsmv,invprc,lev,
research,capintensity,sigmacfo,acquisitions,financing,capital,fog_comp_pres,fog_comp_qa,fog_anal_qa)=0;
run; *60172;

*produce unique PERMNOs;
proc sort data=addcalldata out=uniquefirmIDS (keep=permno) nodupkey; by permno; run;
proc print data=uniquefirmIDS noobs; run;

